 reviews.append({'id':f'REV-{row["id"]}-v{row["version"]}-independent-interface','questionId':row['id'],'questionVersion':row['version'],'questionSha256':question_hash(row),'reviewerId':AUTHOR,'decision':'flagged' if itemflags else 'verified','reviewedAt':now,'sourceVersions':{c['sourceId']:c['sourceSha256'] for c in row['citations']},'reviewedSlideIds':[c['slideId'] for c in row['citations']],'independentAnswerOptionIds':a['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':True,'checks':checks,'reasoning':reasoning,'findings':[f'{k}: {v}' for k,v in itemflags.items()]})
